CREATE FUNCTION public.validate_clinical_rectification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.retifica_id IS NOT NULL THEN IF TG_TABLE_NAME = 'evolucoes' THEN IF NOT EXISTS (SELECT 1 FROM public.evolucoes e WHERE e.id = NEW.retifica_id AND e.paciente_id = NEW.paciente_id) THEN RAISE EXCEPTION 'Rectification must refer to a record of the same patient'; END IF; ELSIF TG_TABLE_NAME = 'prescricoes' THEN IF NOT EXISTS (SELECT 1 FROM public.prescricoes p WHERE p.id = NEW.retifica_id AND p.paciente_id = NEW.paciente_id) THEN RAISE EXCEPTION 'Rectification must refer to a record of the same patient'; END IF; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_evolution_rectification BEFORE INSERT ON public.evolucoes FOR EACH ROW EXECUTE FUNCTION public.validate_clinical_rectification();
CREATE TRIGGER validate_prescription_rectification BEFORE INSERT ON public.prescricoes FOR EACH ROW EXECUTE FUNCTION public.validate_clinical_rectification();